-- Buổi 02 · bảng ghi phẳng mô phỏng (chép tên, lớp vào từng lượt). Lượt 17 ghi lớp khác bảng chuẩn.
CREATE TABLE phieu_phang(idLuot INTEGER PRIMARY KEY,idNguoiMuon INTEGER,tenNguoiMuon TEXT,lop TEXT,maTaiSan TEXT,ngayMuon TEXT);
INSERT INTO phieu_phang SELECT l.idLuotMuon,n.idNguoiMuon,n.tenNguoiMuon,n.lop,t.maTaiSan,l.ngayMuon FROM luot_muon l JOIN nguoi_muon n ON l.idNguoiMuon=n.idNguoiMuon JOIN thiet_bi t ON l.idThietBi=t.idThietBi;
